// Pick RSS feed — rotate through full list, never repeat recently used
const gd = $getWorkflowStaticData('global');
function safeLoad(k) { try { return JSON.parse(gd[k] || '[]'); } catch(e) { return []; } }
let usedFeeds = safeLoad('USED_rss_feeds');
let runCount = parseInt(gd['RUN_count'] || '0') + 1;
gd['RUN_count'] = String(runCount);

const RSS_FEEDS = [
  // BBC Sport
  'https://feeds.bbci.co.uk/sport/rss.xml',
  'https://feeds.bbci.co.uk/sport/football/rss.xml',
  'https://feeds.bbci.co.uk/sport/cricket/rss.xml',
  'https://feeds.bbci.co.uk/sport/tennis/rss.xml',
  'https://feeds.bbci.co.uk/sport/golf/rss.xml',
  'https://feeds.bbci.co.uk/sport/formula1/rss.xml',
  'https://feeds.bbci.co.uk/sport/boxing/rss.xml',
  'https://feeds.bbci.co.uk/sport/rugby-union/rss.xml',
  // The Guardian
  'https://www.theguardian.com/sport/rss',
  'https://www.theguardian.com/football/rss',
  'https://www.theguardian.com/sport/cricket/rss',
  'https://www.theguardian.com/sport/tennis/rss',
  'https://www.theguardian.com/sport/formulaone/rss',
  'https://www.theguardian.com/sport/golf/rss',
  'https://www.theguardian.com/sport/rugby-union/rss',
  // CBS Sports
  'https://www.cbssports.com/rss/headlines/',
  'https://www.cbssports.com/rss/headlines/nfl/',
  'https://www.cbssports.com/rss/headlines/nba/',
  'https://www.cbssports.com/rss/headlines/soccer/',
  'https://www.cbssports.com/rss/headlines/nhl/',
  'https://www.cbssports.com/rss/headlines/mlb/',
  // ESPN
  'https://www.espn.com/espn/rss/news',
  'https://www.espn.com/espn/rss/nfl/news',
  'https://www.espn.com/espn/rss/nba/news',
  'https://www.espn.com/espn/rss/nhl/news',
  'https://www.espn.com/espn/rss/mlb/news',
  // Bleacher Report
  'https://syndication.bleacherreport.com/streams/nba.rss',
  'https://syndication.bleacherreport.com/streams/nfl.rss',
  'https://syndication.bleacherreport.com/streams/soccer.rss',
  // Sky Sports
  'https://www.skysports.com/rss/12040',
  'https://www.skysports.com/rss/12433',
  'https://www.skysports.com/rss/11095',
  'https://www.skysports.com/rss/11902',
  // Soccer
  'https://www.goal.com/feeds/en/news',
  'https://www.90min.com/feeds/latest.rss',
  'https://www.football365.com/feed',
  // Cricket
  'https://www.crictracker.com/feed/',
  'https://www.wisden.com/feed',
  'https://timesofindia.indiatimes.com/rssfeeds/4719148.cms',
  // Others
  'https://hoopshype.com/feed/',
  'https://www.theringer.com/rss/nfl.xml',
  'https://www.theringer.com/rss/nba.xml',
  'https://profootballtalk.nbcsports.com/feed/',
  'https://www.racefans.net/feed/',
  'https://planetf1.com/feed/',
  'https://www.golfweek.com/feed/',
  'https://www.mmajunkie.com/feed',
  'https://mmafighting.com/rss/current',
  'https://www.rugbypass.com/feed/'
];

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length-1; i > 0; i--) { const j = Math.floor(Math.random()*(i+1)); [a[i],a[j]]=[a[j],a[i]]; }
  return a;
}

let available = RSS_FEEDS.filter(f => !usedFeeds.includes(f));
if (available.length < 5) { usedFeeds = []; available = [...RSS_FEEDS]; }

const selected = shuffle(available)[0];
usedFeeds.push(selected);
if (usedFeeds.length > 20) usedFeeds = usedFeeds.slice(-20);
gd['USED_rss_feeds'] = JSON.stringify(usedFeeds);

console.log('Run #' + runCount + ' | 📡 RSS: ' + selected);
return [{ json: { feedUrl: selected, runCount } }];

// Pick best unique sports topic from RSS + extract ALL images with attribution
const items = $input.all();
const gd = $getWorkflowStaticData('global');
function safeLoad(k) { try { return JSON.parse(gd[k] || '[]'); } catch(e) { return []; } }
const EX_titles = safeLoad('EX_titles');
const EX_urls   = safeLoad('EX_urls');
const feedUrl   = $('Pick RSS Feed').first().json.feedUrl || '';

// Determine source name from feed URL
const SOURCE_NAMES = {
  'bbci.co.uk': 'BBC Sport',
  'theguardian.com': 'The Guardian',
  'cbssports.com': 'CBS Sports',
  'espn.com': 'ESPN',
  'bleacherreport.com': 'Bleacher Report',
  'skysports.com': 'Sky Sports',
  'goal.com': 'Goal.com',
  '90min.com': '90min',
  'football365.com': 'Football365',
  'crictracker.com': 'CricTracker',
  'wisden.com': 'Wisden',
  'timesofindia.indiatimes.com': 'Times of India',
  'hoopshype.com': 'HoopsHype',
  'theringer.com': 'The Ringer',
  'nbcsports.com': 'NBC Sports',
  'racefans.net': 'RaceFans',
  'planetf1.com': 'PlanetF1',
  'golfweek.com': 'Golfweek',
  'mmajunkie.com': 'MMA Junkie',
  'mmafighting.com': 'MMA Fighting',
  'rugbypass.com': 'RugbyPass'
};
function getSourceName(url) {
  for (const [domain, name] of Object.entries(SOURCE_NAMES)) {
    if (url && url.includes(domain)) return name;
  }
  return 'Sports News';
}
const sourceName = getSourceName(feedUrl);

const SPORT_KW = ['football','soccer','cricket','tennis','basketball','nba','nfl',
  'formula','f1','premier league','golf','rugby','boxing','olympics','baseball',
  'hockey','sport','match','tournament','championship','league','cup','race',
  'transfer','goal','wimbledon','fifa','ipl','t20','grand slam','ufc','mma','mlb','nhl'];
function isSports(text) { return SPORT_KW.some(kw => (text||'').toLowerCase().includes(kw)); }

const STOP = new Set(['the','and','for','are','but','not','with','from','this','that','they','have','been','will','your','which','news','today','latest']);
function kwWords(t) { return (t||'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').trim().split(' ').filter(w => w.length > 3 && !STOP.has(w)); }
function isDup(a, b) { const wa = kwWords(a), wb = new Set(kwWords(b)); if (!wa.length) return false; return wa.filter(w => wb.has(w)).length / wa.length > 0.45; }

// Extract image from RSS item — check all possible fields
function extractImage(d) {
  // Try every possible RSS image field
  const candidates = [
    d['media:content']?.['$']?.url,
    d['media:content']?.url,
    d['media:thumbnail']?.['$']?.url,
    d['media:thumbnail']?.url,
    d.enclosure?.url,
    d.image?.url,
    d.image,
    d['itunes:image']?.['$']?.href,
  ].filter(u => u && typeof u === 'string' && u.startsWith('http') && u.length > 15);

  // Also try content/description for <img> tags
  const desc = d.content || d['content:encoded'] || d.description || d.summary || '';
  if (typeof desc === 'string') {
    const imgMatch = desc.match(/<img[^>]+src=["']([^"']+)["']/i);
    if (imgMatch && imgMatch[1] && imgMatch[1].startsWith('http')) candidates.push(imgMatch[1]);
  }

  // Filter out tracking pixels and tiny images
  const good = candidates.find(u =>
    !u.includes('pixel') && !u.includes('1x1') && !u.includes('tracking') &&
    !u.includes('spacer') && !u.includes('transparent') && u.length > 20
  );
  return good || '';
}

const candidates = [];
for (const item of items) {
  const d = item.json || {};
  const title = d.title || d.name || '';
  const link  = d.link  || d.url  || d.guid || '';
  const image = extractImage(d);
  const pubDate     = d.pubDate || d.isoDate || d.published || '';
  const description = d.contentSnippet || d.content || d.description || d.summary || '';
  const author      = d.author || d['dc:creator'] || d.creator || sourceName;

  if (!title || title.length < 15) continue;
  if (!isSports(title + ' ' + description)) continue;
  if (link && EX_urls.includes(link)) continue;
  if (EX_titles.some(et => isDup(title, et))) { console.log('Dup: ' + title.substring(0,50)); continue; }

  candidates.push({ title, link, image, description, pubDate, author, sourceName });
}

console.log('📰 Candidates: ' + candidates.length + ' | Feed: ' + sourceName);

if (candidates.length === 0) {
  // Structured fallback topics
  const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const mon = months[new Date().getMonth()]; const yr = new Date().getFullYear();
  const rc  = parseInt($('Pick RSS Feed').first().json.runCount || '1');
  const FALLBACKS = [
    { title: 'Premier League ' + yr + ' Season Analysis: Top Scorers and Standings', description: 'Complete Premier League ' + yr + ' season analysis covering top scorers, standings, key matches and title race predictions.' },
    { title: 'NBA ' + yr + ' Playoffs Race: Standings and Key Matchups', description: 'NBA ' + yr + ' playoffs race update with current standings, team form and predicted first-round matchups.' },
    { title: 'IPL ' + yr + ' Tournament: Team Previews and Predictions', description: 'IPL ' + yr + ' complete tournament preview covering all teams, key players, schedules and expert predictions.' },
    { title: 'Wimbledon ' + yr + ': Top Contenders and Draw Analysis', description: 'Wimbledon ' + yr + ' preview covering top ATP and WTA contenders, draw analysis and tournament predictions.' },
    { title: 'NFL ' + yr + ' Season Preview: Key Storylines and Predictions', description: 'NFL ' + yr + ' season preview with key storylines, team analysis, player predictions and Super Bowl favorites.' },
    { title: 'Formula 1 ' + yr + ' Championship: Drivers and Constructors Standings', description: 'Formula 1 ' + yr + ' championship standings update covering drivers, constructors and upcoming race calendar.' }
  ];
  const fb = FALLBACKS[rc % FALLBACKS.length];
  console.log('⚠️ Fallback: ' + fb.title);
  return [{ json: { title: fb.title, link: '', image: '', description: fb.description, pubDate: new Date().toISOString(), author: '', sourceName: 'YourSportsNation Editorial', allImages: [], hasImages: false } }];
}

// Sort by newest first
candidates.sort((a,b) => {
  const da = a.pubDate ? new Date(a.pubDate).getTime() : 0;
  const db = b.pubDate ? new Date(b.pubDate).getTime() : 0;
  return db - da;
});

// Collect up to 3 unique images from top candidates for inline use
const imagePool = [];
for (const c of candidates.slice(0, 15)) {
  if (imagePool.length >= 3) break;
  if (c.image && c.image.length > 10) {
    imagePool.push({ url: c.image, author: c.author, sourceName: c.sourceName, sourceUrl: c.link });
  }
}

const chosen = candidates[0];
console.log('🎯 Topic: ' + chosen.title);
console.log('🖼️ Images collected: ' + imagePool.length);

return [{ json: {
  ...chosen,
  allImages: imagePool,
  hasImages: imagePool.length > 0
} }];

// Fetch OG images from article pages for items that had no RSS image
// This runs ONLY if we have fewer than 3 images so far
const inp = $json;
const existingImages = inp.allImages || [];

if (existingImages.length >= 3) {
  console.log('Already have ' + existingImages.length + ' images — skip OG fetch');
  return [{ json: inp }];
}

// Try to fetch OG image from the article link itself
async function fetchOgImage(url, sourceName, author, sourceUrl) {
  if (!url || !url.startsWith('http')) return null;
  // Skip sites that block scrapers
  const blocked = ['yahoo.com', 'espn.com', 'nfl.com', 'nba.com', 'paywall'];
  if (blocked.some(d => url.includes(d))) return null;
  try {
    const r = await $http.get(url, {
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)', 'Accept': 'text/html,*/*' },
      timeout: 10000
    });
    const html = r.data || r.body || '';
    if (typeof html !== 'string') return null;
    const og = html.match(/<meta[^>]+property=["']og:image["'][^>]+content=["']([^"']+)["']/i)
            || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:image["']/i);
    if (og && og[1] && og[1].startsWith('http') && !og[1].includes('pixel')) {
      return { url: og[1], author, sourceName, sourceUrl };
    }
    const tw = html.match(/<meta[^>]+name=["']twitter:image["'][^>]+content=["']([^"']+)["']/i)
             || html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+name=["']twitter:image["']/i);
    if (tw && tw[1] && tw[1].startsWith('http') && !tw[1].includes('pixel')) {
      return { url: tw[1], author, sourceName, sourceUrl };
    }
  } catch(e) {}
  return null;
}

const enriched = [...existingImages];
if (enriched.length < 3 && inp.link) {
  console.log('Fetching OG image from: ' + inp.link.substring(0, 60));
  const og = await fetchOgImage(inp.link, inp.sourceName, inp.author, inp.link);
  if (og) { enriched.push(og); console.log('  ✅ OG image found: ' + og.url.substring(0,60)); }
}

console.log('Total images after OG fetch: ' + enriched.length);
return [{ json: { ...inp, allImages: enriched, hasImages: enriched.length > 0 } }];

// Parse Mistral response + strip ALL markdown + fix HTML
const upstream = $('Build Article Request').first().json;
const resp = $json;

let parsed = {}, ok = false;
try {
  const raw = resp.choices?.[0]?.message?.content || '';
  if (!raw || raw.trim().length < 100) {
    console.log('Empty Mistral response: ' + JSON.stringify(resp).substring(0,200));
    return [{ json: { ...upstream, _contentOK: false, _failReason: 'empty_response' } }];
  }
  const clean = raw.replace(/^```json\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```$/,'').trim();
  try { parsed = JSON.parse(clean); ok = true; }
  catch(e1) { const m = clean.match(/\{[\s\S]*\}/); if (m) try { parsed = JSON.parse(m[0]); ok = true; } catch(e2) { console.log('JSON parse fail: ' + e2.message); } }
} catch(e) { console.log('Outer parse err: ' + e.message); }

if (!ok || !parsed.articleHTML || parsed.articleHTML.length < 400) {
  console.log('Bad content — ok:' + ok + ' len:' + (parsed.articleHTML||'').length);
  return [{ json: { ...upstream, _contentOK: false, _failReason: 'bad_html' } }];
}

// ── FULL MARKDOWN → HTML CONVERTER + SANITIZER ──
let html = parsed.articleHTML;

// 1. Convert markdown bold/italic → HTML
html = html.replace(/\*\*\*(.+?)\*\*\*/gs, '<strong><em>$1</em></strong>');
html = html.replace(/\*\*(.+?)\*\*/gs, '<strong>$1</strong>');
html = html.replace(/\*([^\n*]+?)\*/g, '<em>$1</em>');
html = html.replace(/__(.+?)__/gs, '<strong>$1</strong>');
html = html.replace(/_([^\n_]+?)_/g, '<em>$1</em>');

// 2. Convert markdown headings → HTML
html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');
html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
html = html.replace(/^# (.+)$/gm, '<h2>$1</h2>');

// 3. Convert markdown lists
html = html.replace(/^[-*] (.+)$/gm, '<li>$1</li>');
html = html.replace(/(<li>[\s\S]*?<\/li>\s*)+/g, m => '<ul>' + m.trim() + '</ul>');

// 4. Fix unclosed tags
html = html.replace(/<\/p(\s)/gi, '</p>$1');
html = html.replace(/<\/p$/gim, '</p>');
html = html.replace(/<\/(h[1-6])(\s)/gi, '</$1>$2');

// 5. Ensure article wrapper
if (!html.trimStart().startsWith('<article>')) html = '<article>' + html;
if (!html.trimEnd().endsWith('</article>')) html = html + '</article>';

console.log('✅ Article OK: ' + (parsed.title||'').substring(0,65));
console.log('📏 HTML: ' + html.length + ' chars | Sport: ' + (parsed.sport||'general'));

return [{ json: {
  ...upstream,
  _contentOK: true,
  generatedTitle:       parsed.title       || upstream.title,
  generatedSlug:        parsed.slug        || '',
  generatedMeta:        parsed.metaDescription || '',
  generatedKeywords:    parsed.keywords    || [],
  generatedArticleHTML: html,
  generatedSport:       parsed.sport       || 'general'
} }];

// Download first RSS image as binary for WP upload
const inp = $json;
const images = inp.allImages || [];
const firstImg = images[0];

if (!firstImg || !firstImg.url || !firstImg.url.startsWith('http')) {
  console.log('No image to download');
  return [{ json: { ...inp, _imageDownloaded: false, _imgIndex: 0 } }];
}

console.log('⬇️ Downloading image 1: ' + firstImg.url.substring(0,70));
return [{ json: { ...inp, _currentImageUrl: firstImg.url, _imgIndex: 0, _imageDownloaded: true } }];

// Collect uploaded WP media ID
const content = $('Parse Article Response').first().json;
const wpMedia  = $('Upload Image to WP').first().json;

let featuredMediaId = 0;
let featuredWpUrl   = '';

if (wpMedia && wpMedia.id && !isNaN(parseInt(wpMedia.id))) {
  featuredMediaId = parseInt(wpMedia.id);
  featuredWpUrl   = wpMedia.source_url || wpMedia.guid?.rendered || '';
  console.log('✅ Featured image uploaded. WP ID: ' + featuredMediaId);
} else {
  console.log('⚠️ Featured image upload failed — will publish without featured image');
}

return [{ json: {
  ...content,
  _featuredMediaId: featuredMediaId,
  _featuredWpUrl:   featuredWpUrl
} }];

// BUILD FINAL WP POST
// - Inline images at correct h2 positions with proper attribution
// - Copyright disclaimer at bottom
// - Correct WP categories
// - Unique slug with timestamp
const inp = $json;
const gd = $getWorkflowStaticData('global');
function safeLoad(k) { try { return JSON.parse(gd[k] || '[]'); } catch(e) { return []; } }

// Duplicate check
const EX_titles = safeLoad('EX_titles');
const genTitle  = (inp.generatedTitle || inp.title || '').toLowerCase();
const STOP = new Set(['the','and','for','are','but','not','with','from','this','that','they','have','been','will','your','which','news','today','latest','about']);
function kwW(t) { return t.toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(' ').filter(w=>w.length>3&&!STOP.has(w)); }
function isDup(a,b) { const wa=kwW(a),wb=new Set(kwW(b)); return wa.length&&wa.filter(w=>wb.has(w)).length/wa.length>0.5; }

if (EX_titles.some(t => isDup(genTitle, t))) {
  console.log('🚫 DUPLICATE — skipping: ' + genTitle.substring(0,60));
  return [{ json: { _postBody: null, _isDuplicate: true, _topicTitle: inp.generatedTitle, _topicSlug: '', _topicUrl: inp.link||'' } }];
}

const title       = inp.generatedTitle || inp.title || 'Sports News';
const articleHTML = inp.generatedArticleHTML || '';
const meta        = inp.generatedMeta || '';
const keywords    = inp.generatedKeywords || [];
const allImages   = inp.allImages || [];
const featuredMediaId = inp._featuredMediaId || 0;
const featuredWpUrl   = inp._featuredWpUrl || '';

// ── INLINE IMAGE FIGURE BUILDER with attribution ──
function makeFig(imageObj, altText) {
  if (!imageObj || !imageObj.url || imageObj.url.length < 10) return '';
  const alt  = (altText || title).replace(/["<>&]/g, '').substring(0, 120);
  const sn   = imageObj.sourceName || 'Sports News';
  const au   = imageObj.author || sn;
  const su   = imageObj.sourceUrl || inp.link || '';

  // Attribution credit line — just like newspapers do it
  const credit = su
    ? `Photo credit: <a href="${su}" rel="nofollow noopener" target="_blank">${sn}</a>${au && au !== sn ? ' / ' + au : ''}`
    : `Photo credit: ${sn}${au && au !== sn ? ' / ' + au : ''}`;

  return `\n<figure class="wp-block-image size-large" style="margin:32px 0 24px;">` +
    `<img src="${imageObj.url}" alt="${alt}" loading="lazy" ` +
    `style="width:100%;height:auto;max-width:1200px;display:block;margin:0 auto;border-radius:6px;box-shadow:0 2px 12px rgba(0,0,0,0.12);" />` +
    `<figcaption style="text-align:center;font-size:12px;color:#888;margin-top:6px;font-style:italic;">${credit}</figcaption>` +
    `</figure>\n`;
}

// Find good insert position after a h2 section (after last </p> before next <h2>)
function insertAfterSection(html, h2EndPos) {
  const nextH2 = html.indexOf('<h2', h2EndPos);
  const secEnd = nextH2 !== -1 ? nextH2 : html.length;
  const section = html.substring(h2EndPos, secEnd);
  const lastP = section.lastIndexOf('</p>');
  return lastP !== -1 ? h2EndPos + lastP + 4 : h2EndPos;
}

// Collect h2 end positions
const h2Ends = [];
const h2Re = /<\/h2>/gi; let match;
while ((match = h2Re.exec(articleHTML)) !== null) h2Ends.push(match.index + match[0].length);
console.log('H2 sections: ' + h2Ends.length + ' | Images available: ' + allImages.length);

let finalHTML = articleHTML;

// Insert image 1 — after 2nd h2 (index 1)
if (allImages[0] && h2Ends.length >= 2) {
  const pos = insertAfterSection(finalHTML, h2Ends[1]);
  // Get the h2 text for better alt text
  const h2TextMatch = finalHTML.substring(h2Ends[1]-200, h2Ends[1]).match(/<h2[^>]*>([^<]+)<\/h2>\s*$/);
  const h2Alt = h2TextMatch ? h2TextMatch[1].trim() : title;
  const fig = makeFig(allImages[0], h2Alt);
  if (fig) {
    finalHTML = finalHTML.substring(0, pos) + fig + finalHTML.substring(pos);
    console.log('✅ Image 1 inserted after h2[1]');
  }
}

// Insert image 2 — after 4th h2 (index 3) if available
if (allImages[1] && h2Ends.length >= 4) {
  // Recompute h2Ends after first insertion
  const h2Ends2 = [];
  const h2Re2 = /<\/h2>/gi; let m2;
  while ((m2 = h2Re2.exec(finalHTML)) !== null) h2Ends2.push(m2.index + m2[0].length);
  if (h2Ends2[3]) {
    const pos2 = insertAfterSection(finalHTML, h2Ends2[3]);
    const fig2 = makeFig(allImages[1], title);
    if (fig2) {
      finalHTML = finalHTML.substring(0, pos2) + fig2 + finalHTML.substring(pos2);
      console.log('✅ Image 2 inserted after h2[3]');
    }
  }
}

// Insert image 3 — before </article> closing if available
if (allImages[2]) {
  const fig3 = makeFig(allImages[2], title);
  if (fig3) {
    const closePos = finalHTML.lastIndexOf('</article>');
    if (closePos !== -1) {
      finalHTML = finalHTML.substring(0, closePos) + fig3 + finalHTML.substring(closePos);
    } else {
      finalHTML += fig3;
    }
    console.log('✅ Image 3 inserted before </article>');
  }
}

// Source attribution badge
if (inp.link) {
  const srcBadge = `<p style="font-size:12px;color:#999;border-top:1px solid #eee;margin-top:20px;padding-top:10px;">📡 Original source: <a href="${inp.link}" rel="nofollow noopener" target="_blank">${inp.sourceName || 'Sports Feed'}</a></p>`;
  finalHTML = finalHTML.includes('</article>') ? finalHTML.replace('</article>', srcBadge + '</article>') : finalHTML + srcBadge;
}

// Copyright + attribution disclaimer at bottom of every article
const disclaimer = `
<div style="background:#f9f9f9;border-left:4px solid #0073aa;padding:16px 20px;margin-top:28px;font-size:12px;color:#555;line-height:1.8;border-radius:0 6px 6px 0;">
